-- Правила и запреты рыболовства (M5a): зоны на карте и ограничения по датам.
--
-- Первоисточники:
--  * приказ Министра сельского хозяйства РК от 3 марта 2026 года № 78 «О введении ограничений и
--    запретов на пользование объектами рыбных ресурсов и других водных животных, их частей и
--    дериватов, установлении мест и сроков их пользования» (зарегистрирован 10 марта 2026 года
--    № 38112), глава 3 приложения 1 — Балкаш-Алакольский бассейн;
--  * Правила рыболовства (приказ и. о. Министра сельского хозяйства РК от 27 февраля 2015 года
--    № 18-04/148), приложение 1 — промысловая мера.
-- Сроки — «соответствующего года», то есть каждый год. Данные сверены 30 сентября 2026 года.
--
-- Границы зон — по данным OpenStreetMap (© участники OpenStreetMap, ODbL), упрощённые и
-- приблизительные; как они получены — supabase/data/rules. Текст правила важнее границы на карте.
-- Справочник читают все, в том числе гости; меняют — только в Supabase Studio.

create type public.rule_zone_kind as enum ('reservoir', 'lake', 'river', 'delta', 'rest_zone');

create table public.rule_zones (
  id          text primary key check (id ~ '^[a-z0-9_]{2,40}$'),
  kind        public.rule_zone_kind not null,
  basin       text not null,
  name_ru     text not null,
  name_kk     text not null,
  name_en     text not null,
  -- Что не показано на карте или показано приблизительно.
  note_ru     text,
  note_kk     text,
  note_en     text,
  -- null — граница на карте не нанесена, правило действует по тексту.
  geom        extensions.geometry(MultiPolygon, 4326),
  sort_order  integer not null default 100
);

create index rule_zones_geom_idx on public.rule_zones using gist (geom);

create type public.regulation_kind as enum ('fishing_ban', 'min_size', 'method_ban', 'info');

-- all — любое рыболовство; amateur — любительскими (непромысловыми) орудиями лова.
create type public.regulation_gear as enum ('all', 'amateur');

create table public.regulations (
  id            text primary key check (id ~ '^[a-z0-9_]{2,60}$'),
  kind          public.regulation_kind not null,
  basin         text not null,
  -- Зоны, где действует правило; пусто — везде (общие правила).
  zone_ids      text[] not null default '{}',
  gear          public.regulation_gear not null default 'all',
  -- Каждый год с (месяц, день) по (месяц, день) включительно; все null — круглый год.
  start_month   smallint check (start_month between 1 and 12),
  start_day     smallint check (start_day between 1 and 31),
  end_month     smallint check (end_month between 1 and 12),
  end_day       smallint check (end_day between 1 and 31),
  -- Промысловая мера: вид (fish_species.id) → см.
  min_sizes     jsonb check (min_sizes is null or jsonb_typeof(min_sizes) = 'object'),
  title_ru      text not null,
  title_kk      text not null,
  title_en      text not null,
  body_ru       text not null,
  body_kk       text not null,
  body_en       text not null,
  source_title  text not null,
  source_url    text not null check (source_url ~ '^https://'),
  source_clause text not null,
  verified_on   date not null,
  sort_order    integer not null default 100,
  check (
    (start_month is null and start_day is null and end_month is null and end_day is null)
    or (start_month is not null and start_day is not null and end_month is not null and end_day is not null)
  ),
  -- Несуществующая дата (31 апреля) — ошибка при вставке.
  check (start_month is null or make_date(2000, start_month, start_day) is not null),
  check (end_month is null or make_date(2000, end_month, end_day) is not null)
);

alter table public.rule_zones enable row level security;
alter table public.regulations enable row level security;

revoke all on table public.rule_zones, public.regulations from anon, authenticated;
grant select on table public.rule_zones, public.regulations to anon, authenticated;

create policy "rule_zones: читать всем" on public.rule_zones
  for select to anon, authenticated using (true);
create policy "regulations: читать всем" on public.regulations
  for select to anon, authenticated using (true);

-- Период правила, который идёт в день p_on или начнётся следующим (включительно). null —
-- круглый год. Период может переходить через Новый год (1 декабря – 28 февраля).
create function private.rule_period(
  p_start_month smallint,
  p_start_day smallint,
  p_end_month smallint,
  p_end_day smallint,
  p_on date
) returns daterange
language plpgsql
immutable
set search_path = ''
as $$
declare
  y integer := extract(year from p_on)::integer;
  s date;
  e date;
begin
  if p_start_month is null then
    return null;
  end if;
  s := make_date(y, p_start_month, least(p_start_day, private.days_in_month(y, p_start_month)));
  e := make_date(y, p_end_month, least(p_end_day, private.days_in_month(y, p_end_month)));
  if s <= e then
    if p_on > e then
      s := make_date(y + 1, p_start_month, least(p_start_day, private.days_in_month(y + 1, p_start_month)));
      e := make_date(y + 1, p_end_month, least(p_end_day, private.days_in_month(y + 1, p_end_month)));
    end if;
  elsif p_on <= e then
    s := make_date(y - 1, p_start_month, least(p_start_day, private.days_in_month(y - 1, p_start_month)));
  else
    e := make_date(y + 1, p_end_month, least(p_end_day, private.days_in_month(y + 1, p_end_month)));
  end if;
  return daterange(s, e, '[]');
end;
$$;

create function private.days_in_month(p_year integer, p_month smallint) returns integer
language sql
immutable
set search_path = ''
as $$
  select extract(day from (make_date(p_year, p_month, 1) + interval '1 month - 1 day'))::integer;
$$;

-- Правила в точке на дату (по умолчанию — сегодня по Алматы): общие и зон, в которые попала
-- точка. active — действует в этот день; period_start/period_end — текущий или ближайший период.
create function public.regulations_at(p_lon double precision, p_lat double precision, p_on date default null)
returns table (
  regulation_id text,
  kind public.regulation_kind,
  gear public.regulation_gear,
  zone_id text,
  active boolean,
  period_start date,
  period_end date,
  min_sizes jsonb
)
language sql
stable
security definer
set search_path = ''
as $$
  with day as (
    select coalesce(p_on, (now() at time zone 'Asia/Almaty')::date) as d
  ),
  here as (
    select z.id
      from public.rule_zones z
     where z.geom is not null
       and extensions.st_intersects(z.geom, extensions.st_setsrid(extensions.st_makepoint(p_lon, p_lat), 4326))
  )
  select r.id, r.kind, r.gear, h.id,
         per.p is null or day.d <@ per.p,
         lower(per.p), upper(per.p) - 1,
         r.min_sizes
    from public.regulations r
    cross join day
    left join here h on h.id = any (r.zone_ids)
    cross join lateral (
      select private.rule_period(r.start_month, r.start_day, r.end_month, r.end_day, day.d) as p
    ) per
   where cardinality(r.zone_ids) = 0 or h.id is not null
   order by r.sort_order, r.id;
$$;

revoke execute on function public.regulations_at(double precision, double precision, date) from public;
grant execute on function public.regulations_at(double precision, double precision, date) to anon, authenticated;

