insert into public.regulations
  (id, kind, basin, zone_ids, gear, start_month, start_day, end_month, end_day, min_sizes,
   title_ru, title_kk, title_en, body_ru, body_kk, body_en,
   source_title, source_url, source_clause, verified_on, sort_order)
values
  ('kapshagay_spawning', 'fishing_ban', 'balkhash_alakol', '{kapshagay}', 'all', 4, 5, 5, 20, null,
   'Нерестовый запрет', 'Уылдырық шашу кезеңіндегі тыйым', 'Spawning ban',
   'Любое рыболовство запрещено на водохранилище Капшагай и на всех реках и водотоках, впадающих в него.',
   'Қапшағай су қоймасында және оған құятын барлық өзендер мен су ағындарында балық аулаудың кез келген түріне тыйым салынады.',
   'All fishing is banned on Kapshagay Reservoir and on all rivers and streams flowing into it.',
   'Приказ Министра сельского хозяйства РК от 3 марта 2026 года № 78', 'https://adilet.zan.kz/rus/docs/V2600038112',
   'прил. 1, п. 7, пп. 3', '2026-09-30', 10),

  ('ile_backwater_rest', 'fishing_ban', 'balkhash_alakol', '{ile_backwater}', 'all', null, null, null, null, null,
   'Зона покоя: рыболовство запрещено круглый год', 'Тыныштық аймағы: балық аулауға жыл бойы тыйым салынады', 'Rest zone: fishing banned all year',
   'Круглый год запрещено любое рыболовство в зоне подпора: от прямой между сопкой Утюги (левый берег водохранилища) и бывшим 90-м км (правый берег) вверх по реке Иле до устья реки Шарын.',
   'Тірек аймағында балық аулаудың кез келген түріне жыл бойы тыйым салынады: Утюги төбесі (су қоймасының сол жағалауы) мен бұрынғы 90-шы км (оң жағалау) арасындағы түзуден Іле өзені бойымен жоғары Шарын өзенінің сағасына дейін.',
   'All fishing is banned all year in the backwater zone: from the straight line between Utyugi hill (left bank of the reservoir) and former km 90 (right bank) up the Ile to the Sharyn mouth.',
   'Приказ Министра сельского хозяйства РК от 3 марта 2026 года № 78', 'https://adilet.zan.kz/rus/docs/V2600038112',
   'прил. 1, п. 8, пп. 3', '2026-09-30', 20),

  ('ile_dam_araltobe_spawning', 'fishing_ban', 'balkhash_alakol', '{ile_dam_araltobe}', 'amateur', 4, 5, 6, 5, null,
   'Нерестовый запрет для удочек и спиннингов', 'Қармақ пен спиннингке уылдырық шашу кезеңіндегі тыйым', 'Spawning ban for rods and spinning',
   'Запрещено рыболовство непромысловыми (любительскими) орудиями лова на реке Иле от плотины Капшагайской ГЭС до 6-го рыбпункта (посёлок Арал-Тюбе). Промысловые орудия здесь запрещены круглый год.',
   'Іле өзенінде Қапшағай СЭС бөгетінен 6-шы балық пунктіне (Арал-Төбе кенті) дейін кәсіптік емес (әуесқойлық) аулау құралдарымен балық аулауға тыйым салынады. Кәсіптік аулау құралдарына мұнда жыл бойы тыйым салынған.',
   'Fishing with non-commercial (amateur) gear is banned on the Ile from the Kapshagay hydro dam to fish station 6 (Aral-Tobe village). Commercial gear is banned here all year.',
   'Приказ Министра сельского хозяйства РК от 3 марта 2026 года № 78', 'https://adilet.zan.kz/rus/docs/V2600038112',
   'прил. 1, п. 7, пп. 5; п. 8, пп. 1', '2026-09-30', 30),

  ('ile_delta_spawning', 'fishing_ban', 'balkhash_alakol', '{ile_delta}', 'amateur', 4, 15, 6, 1, null,
   'Нерестовый запрет для удочек и спиннингов', 'Қармақ пен спиннингке уылдырық шашу кезеңіндегі тыйым', 'Spawning ban for rods and spinning',
   'Запрещено рыболовство непромысловыми (любительскими) орудиями лова на всей дельте реки Иле. Промысловые орудия здесь запрещены круглый год.',
   'Іле өзенінің бүкіл атырауында кәсіптік емес (әуесқойлық) аулау құралдарымен балық аулауға тыйым салынады. Кәсіптік аулау құралдарына мұнда жыл бойы тыйым салынған.',
   'Fishing with non-commercial (amateur) gear is banned in the whole Ile delta. Commercial gear is banned here all year.',
   'Приказ Министра сельского хозяйства РК от 3 марта 2026 года № 78', 'https://adilet.zan.kz/rus/docs/V2600038112',
   'прил. 1, п. 7, пп. 6; п. 8, пп. 1', '2026-09-30', 40),

  ('ile_sharyn_china_spawning', 'fishing_ban', 'balkhash_alakol', '{ile_sharyn_china}', 'amateur', 3, 25, 7, 5, null,
   'Нерестовый запрет для удочек и спиннингов', 'Қармақ пен спиннингке уылдырық шашу кезеңіндегі тыйым', 'Spawning ban for rods and spinning',
   'Запрещено рыболовство непромысловыми (любительскими) орудиями лова на реке Иле от устья реки Шарын до государственной границы с КНР. Промысловые орудия здесь запрещены круглый год.',
   'Іле өзенінде Шарын өзенінің сағасынан ҚХР-мен мемлекеттік шекараға дейін кәсіптік емес (әуесқойлық) аулау құралдарымен балық аулауға тыйым салынады. Кәсіптік аулау құралдарына мұнда жыл бойы тыйым салынған.',
   'Fishing with non-commercial (amateur) gear is banned on the Ile from the Sharyn mouth to the state border with China. Commercial gear is banned here all year.',
   'Приказ Министра сельского хозяйства РК от 3 марта 2026 года № 78', 'https://adilet.zan.kz/rus/docs/V2600038112',
   'прил. 1, п. 7, пп. 7; п. 8, пп. 2', '2026-09-30', 50),

  ('balkhash_west_spawning', 'fishing_ban', 'balkhash_alakol', '{balkhash_west}', 'all', 4, 15, 6, 1, null,
   'Нерестовый запрет', 'Уылдырық шашу кезеңіндегі тыйым', 'Spawning ban',
   'Любое рыболовство запрещено в западной части озера Балхаш — от южной оконечности залива Алаколь до полуострова Узынарал.',
   'Балқаш көлінің батыс бөлігінде — Алакөл шығанағының оңтүстік шетінен Ұзынарал түбегіне дейін — балық аулаудың кез келген түріне тыйым салынады.',
   'All fishing is banned in the western part of Lake Balkhash, from the southern tip of Alakol Bay to the Uzynaral peninsula.',
   'Приказ Министра сельского хозяйства РК от 3 марта 2026 года № 78', 'https://adilet.zan.kz/rus/docs/V2600038112',
